#!/usr/bin/env node
// Compiles the canonical auto-activation bootstrap into provider-specific assets.
// Hooks stay dependency-free (no imports, no repo reads, no network) so they start fast;
// drift between these generated files and runtime/activation.mjs is a test failure.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {BOOTSTRAP_TEXT,bootstrapHash,getActivationPolicy} from '../runtime/activation.mjs';

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const policy=getActivationPolicy();
const HASH=bootstrapHash();
const TEXT=JSON.stringify(BOOTSTRAP_TEXT);
const GEN='// GENERATED by scripts/gen-activation-assets.mjs from runtime/activation.mjs. Do not edit by hand.';
const SOURCES=JSON.stringify(policy.hosts.claude.reinjection_sources);

const claudeHook=`#!/usr/bin/env node
${GEN}
// Claude Code SessionStart hook: delivers one compact auto-activation invariant.
// bootstrap_version=${policy.bootstrap_version} bootstrap_hash=${HASH}
const BOOTSTRAP=${TEXT};
const SOURCES=new Set(${SOURCES});
const DISABLED=v=>['0','false','no','off','disabled'].includes(String(v??'').trim().toLowerCase());
let raw='';
for await (const c of process.stdin)raw+=c;
if(DISABLED(process.env.AGENT_SDLC_AUTO_ACTIVATE_ENFORCED)||DISABLED(process.env.${policy.env_override}))process.exit(0);
let p={};try{p=JSON.parse(raw||'{}');}catch{p={};}
const source=String(p.session_start_reason||p.source||p.matcher||'startup');
if(!SOURCES.has(source))process.exit(0);
console.log(JSON.stringify({hookSpecificOutput:{hookEventName:'SessionStart',additionalContext:BOOTSTRAP}}));
`;

const antigravityHook=`#!/usr/bin/env node
${GEN}
// Antigravity PreInvocation hook: delivers one compact auto-activation invariant as an
// ephemeral message. It injects instructions only; it never widens tool permissions.
// bootstrap_version=${policy.bootstrap_version} bootstrap_hash=${HASH}
const BOOTSTRAP=${TEXT};
const DISABLED=v=>['0','false','no','off','disabled'].includes(String(v??'').trim().toLowerCase());
for await (const _ of process.stdin){}
if(DISABLED(process.env.AGENT_SDLC_AUTO_ACTIVATE_ENFORCED)||DISABLED(process.env.${policy.env_override}))process.exit(0);
console.log(JSON.stringify({injectSteps:[{ephemeralMessage:BOOTSTRAP}]}));
`;

const rules=`<!-- GENERATED by scripts/gen-activation-assets.mjs. Do not edit by hand. -->
# Agent SDLC plugin rule

${BOOTSTRAP_TEXT}

Keep context bounded, prefer deterministic evidence over model inference, and require the workflow gate evidence before claiming completion.
`;

// The same-root GitHub install and the built packages both resolve hook commands as
// ${PLUGIN_ROOT}/hooks/<file>, so the canonical adapter hooks are mirrored into hooks/.
const outputs=[
  ['adapters/hooks/claude-session-start.mjs',claudeHook],
  ['hooks/claude-session-start.mjs',claudeHook],
  ['hooks/pretool-guard.mjs',fs.readFileSync(path.join(ROOT,'adapters/hooks/pretool-guard.mjs'),'utf8')],
  ['adapters/hooks/antigravity-preinvocation.mjs',antigravityHook],
  ['hooks/antigravity-preinvocation.mjs',antigravityHook],
  ['adapters/antigravity/rules.md',rules],
  ['rules/agent-sdlc.md',rules]
];
const written=[];
for(const [rel,text] of outputs){
  const abs=path.join(ROOT,rel);
  fs.mkdirSync(path.dirname(abs),{recursive:true});
  const current=fs.existsSync(abs)?fs.readFileSync(abs,'utf8'):null;
  if(current!==text)fs.writeFileSync(abs,text);
  written.push({file:rel,changed:current!==text});
}
console.log(JSON.stringify({schema:'agent-sdlc/activation-assets/v1',bootstrap_version:policy.bootstrap_version,bootstrap_hash:HASH,bootstrap_chars:BOOTSTRAP_TEXT.length,outputs:written},null,2));
